import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 210;
    static final int INF = 0x3f3f3f3f;
    static int n, T;
    static int startX, startY;
    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {-1, 1, 0, 0};
    static char[][] maze1 = new char[MAXN][MAXN];
    static char[][] maze2 = new char[MAXN][MAXN];
    static int[][] distMap = new int[MAXN][MAXN];
    static int[][] visited = new int[MAXN][MAXN];

    static class FlowNetwork {
        int[][] cap = new int[MAXN * MAXN][MAXN * MAXN];
        int[][] flow = new int[MAXN * MAXN][MAXN * MAXN];
        int[][] adj = new int[MAXN * MAXN][MAXN * MAXN];
        int[] deg = new int[MAXN * MAXN];
        int nodeCount, s, t;
        int[] height = new int[MAXN * MAXN];
        int[] countH = new int[MAXN * MAXN];

        void init(int n) {
            nodeCount = n;
            for (int i = 0; i < MAXN * MAXN; i++) {
                Arrays.fill(cap[i], 0);
                Arrays.fill(flow[i], 0);
                Arrays.fill(adj[i], 0);
                deg[i] = 0;
            }
            for (int i = 0; i <= n; i++) {
                height[i] = 0;
                countH[i] = 0;
            }
        }

        void addEdge(int u, int v, int c) {
            cap[u][v] += c;
            if (adj[u][v] == 0) {
                adj[u][v] = 1;
                deg[u]++;
            }
        }

        int sendFlow(int u, int flowIn) {
            if (u == t) return flowIn;
            int totalFlow = 0;
            for (int v = 0; v < nodeCount; v++) {
                if (cap[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                    int pushed = Math.min(flowIn, cap[u][v] - flow[u][v]);
                    int pushedFlow = sendFlow(v, pushed);
                    if (pushedFlow > 0) {
                        flow[u][v] += pushedFlow;
                        flow[v][u] -= pushedFlow;
                        totalFlow += pushedFlow;
                        flowIn -= pushedFlow;
                        if (flowIn == 0) break;
                    }
                }
            }
            if (totalFlow == 0) {
                int minH = nodeCount;
                for (int v = 0; v < nodeCount; v++) {
                    if (cap[u][v] - flow[u][v] > 0) minH = Math.min(minH, height[v]);
                }
                if (--countH[height[u]] == 0) height[s] = nodeCount;
                height[u] = minH + 1;
                countH[height[u]]++;
            }
            return totalFlow;
        }

        int maxFlow(int s_, int t_) {
            s = s_; t = t_;
            for (int i = 0; i < MAXN * MAXN; i++) {
                Arrays.fill(flow[i], 0);
                Arrays.fill(height, 0);
            }
            Arrays.fill(countH, 0);
            for (int i = 0; i <= nodeCount; i++) height[i] = 0;
            countH[0] = nodeCount;
            int totalFlow = 0;
            while (height[s] < nodeCount) {
                totalFlow += sendFlow(s, INF);
            }
            return totalFlow;
        }
    }

    static class Point {
        int x, y, dist;
        Point(int x, int y, int dist) {
            this.x = x;
            this.y = y;
            this.dist = dist;
        }
    }

    static int nodeID(int i, int j) {
        return (i - 1) * n + j;
    }

    static boolean inRange(int x, int y) {
        return x >= 1 && x <= n && y >= 1 && y <= n;
    }

    static void BFS1() {
        Queue<Point> q = new LinkedList<>();
        Point p, np;
        p = new Point(startX, startY, 0);
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(distMap[i], Integer.MAX_VALUE);
        }
        for (int i = 0; i < MAXN; i++) {
            Arrays.fill(visited[i], 0);
        }
        visited[startX][startY] = 1;
        q.offer(p);
        while (!q.isEmpty()) {
            p = q.poll();
            distMap[p.x][p.y] = p.dist;
            if (p.dist > T) break;
            for (int k = 0; k < 4; k++) {
                int nx = p.x + dx[k], ny = p.y + dy[k];
                if (inRange(nx, ny) && maze1[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    np = new Point(nx, ny, p.dist + 1);
                    visited[nx][ny] = 1;
                    q.offer(np);
                }
            }
        }
    }

    static void BFS2(int i, int j, FlowNetwork maxFlow) {
        Queue<Point> q = new LinkedList<>();
        Point p, np;
        p = new Point(i, j, 0);
        for (int k = 0; k < MAXN; k++) {
            Arrays.fill(visited[k], 0);
        }
        visited[i][j] = 1;
        q.offer(p);
        while (!q.isEmpty()) {
            p = q.poll();
            if (p.dist > T) break;
            if (distMap[p.x][p.y] < p.dist) continue;
            if ((distMap[p.x][p.y] == p.dist && maze2[p.x][p.y] < '1') || maze2[p.x][p.y] > '9') continue;
            if (maze2[p.x][p.y] >= '1' && maze2[p.x][p.y] <= '9') {
                if (p.x != i || p.y != j)
                    maxFlow.addEdge(nodeID(i, j), nodeID(p.x, p.y) + n * n, INF);
                if (distMap[p.x][p.y] == p.dist) continue;
            }
            for (int k = 0; k < 4; k++) {
                int nx = p.x + dx[k], ny = p.y + dy[k];
                if (inRange(nx, ny) && maze1[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    np = new Point(nx, ny, p.dist + 1);
                    visited[nx][ny] = 1;
                    q.offer(np);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            maze1[i] = new char[MAXN];
            for (int j = 1; j <= n; j++) {
                maze1[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            maze2[i] = new char[MAXN];
            for (int j = 1; j <= n; j++) {
                maze2[i][j] = line.charAt(j - 1);
            }
        }
        int s = 0, e = 2 * n * n + 1;
        FlowNetwork maxFlow = new FlowNetwork();
        maxFlow.init(e + 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] >= '1' && maze1[i][j] <= '9') {
                    maxFlow.addEdge(s, nodeID(i, j), maze1[i][j] - '0');
                }
                if (maze1[i][j] == 'Z') {
                    startX = i;
                    startY = j;
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                maxFlow.addEdge(nodeID(i, j), nodeID(i, j) + n * n, INF);
                if (maze2[i][j] >= '1' && maze2[i][j] <= '9') {
                    maxFlow.addEdge(nodeID(i, j) + n * n, e, maze2[i][j] - '0');
                }
            }
        }
        BFS1();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] >= '1' && maze1[i][j] <= '9') {
                    BFS2(i, j, maxFlow);
                }
            }
        }
        int res = maxFlow.maxFlow(s, e);
        System.out.println(res);
    }
}

